"""CONF-DATA-001: the committed ledger and campaign record are regenerated byte for byte; every gate holds; the code
uses only the standard library."""
from __future__ import annotations

import ast
import json
import unittest
from pathlib import Path

import _ledger

HERE = Path(__file__).resolve().parent
CODE = ("_judge.py", "_sim.py", "_ledger.py")
ALLOWED_IMPORTS = {"__future__", "hashlib", "json", "pathlib", "random", "_judge", "_sim"}


class LedgerTests(unittest.TestCase):
    def test_the_committed_ledger_is_regenerated_byte_for_byte(self):
        """CI's python3 uses its own hash seed, so this also catches any dependence on hash order."""
        self.assertEqual(_ledger.serialize(_ledger.ledger()), (HERE / "results.json").read_bytes())

    def test_the_committed_campaign_record_is_regenerated_byte_for_byte(self):
        self.assertEqual(_ledger.serialize(_ledger.campaign_record(_ledger.ledger())),
                         (HERE / "campaign-record.json").read_bytes())

    def test_a_second_in_process_build_is_identical(self):
        self.assertEqual(_ledger.serialize(_ledger.build()), _ledger.serialize(_ledger.ledger()))

    def test_every_gate_holds_and_every_case_passes(self):
        led = _ledger.ledger()
        for row in led["cases"]:
            for arm in row["arms"]:
                with self.subTest(case=row["id"], arm=arm["name"]):
                    self.assertTrue(arm["gate"])
                    self.assertEqual((arm["runs"], arm["errored"], arm["agreements"], arm["violationWithoutBreak"]),
                                     (32, 0, 32, 0))
            self.assertEqual(row["result"], "PASS", row["id"])
        self.assertEqual(led["summary"], {"arms": 60, "cases": 29, "casesPassed": 29, "golden": 13, "goldenAgreed": 13,
                                          "r12Extensions": ["CK-04", "CV-04", "DD-04"], "runs": 1920})

    def test_controls_are_caught_and_defended_arms_are_clean(self):
        for row in _ledger.ledger()["cases"]:
            for arm in row["arms"]:
                if arm["kind"] == "DEFENDED":
                    self.assertEqual((arm["broken"], arm["violations"], arm["refusals"]), (0, 0, {}), row["id"])
                else:
                    self.assertGreaterEqual(arm["violations"], arm["floor"], (row["id"], arm["name"]))
                    self.assertEqual(set(arm["refusals"]), {arm["code"]}, (row["id"], arm["name"]))

    def test_the_campaign_record_labels_the_extensions_and_states_its_role(self):
        record = _ledger.campaign_record(_ledger.ledger())
        self.assertEqual(record["consumer"], "CONF-A3-001")
        self.assertIn("not a gate", record["role"])
        ext = [c for c in record["cases"] if c["authoredBy"] == "R12"]
        self.assertEqual([c["id"] for c in ext], ["CK-04", "CV-04", "DD-04"])
        self.assertTrue(all(c["parity"] == "R12_EXTENSION" and c["provisional"] and c["expectedArmsBy"] == "R12"
                            for c in ext))
        self.assertIn("never conformance to the merged record's 13", record["r12Extensions"]["note"])
        self.assertEqual(len(record["residuals"]["DD-04"]), 3)

    def test_the_code_imports_only_the_standard_library_and_reads_no_clock(self):
        for name in CODE:
            tree = ast.parse((HERE / name).read_text(encoding="ascii"))
            imported = set()
            for node in ast.walk(tree):
                if isinstance(node, ast.Import):
                    imported |= {a.name.split(".")[0] for a in node.names}
                elif isinstance(node, ast.ImportFrom):
                    imported.add(node.module.split(".")[0])
            self.assertLessEqual(imported, ALLOWED_IMPORTS, name)
            self.assertNotIn("time", imported, name)


if __name__ == "__main__":
    unittest.main()
